console.log('fill latency: '+lat+' cycles — deep pipelines win on throughput, not latency');

// Demo: AXI-Stream Interfaces — AXI-stream handshake simulation
var beats=17,sent=0,stalled=0,ready=true;
for(var i=0;i<beats;i++){ready=((i*13+3)%5)!==0;if(ready)sent++;else stalled++;}
console.log('technique: AXI-Stream Interfaces');console.log('beats: '+beats+', transferred: '+sent+', stalled: '+stalled);
console.log('backpressure handled — no data lost');

// Demo: DSP Slice Mapping — fixed-point quantization error
var bits=23%8+8;var maxErr=1/Math.pow(2,bits);
console.log('technique: DSP Slice Mapping');console.log('fractional bits: '+bits);
console.log('max quantization error: '+maxErr.toExponential(2));
console.log(bits>=16?'ok for most DSP chains':'consider more bits for precision-critical paths');

